import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

// Environmental Science lessons with videos
const ENVIRONMENTAL_SCIENCE_LESSONS = [
  {
    lesson_number: 1,
    title: "Ecosystems & Biomes",
    videos: [
      { id: 1, title: "What is an Ecosystem?", url: "https://www.youtube.com/embed/bBjbhHXPMww" },
      { id: 2, title: "Biomes Around the World", url: "https://www.youtube.com/embed/xz5w1FT9rwg" },
      { id: 3, title: "Tropical Rainforests", url: "https://www.youtube.com/embed/jXXa2fV1i54" },
      { id: 4, title: "Deserts & Grasslands", url: "https://www.youtube.com/embed/5qMaAfQrGTc" },
      { id: 5, title: "Polar & Temperate Regions", url: "https://www.youtube.com/embed/N3gN8Uw9DT8" }
    ]
  },
  {
    lesson_number: 2,
    title: "Energy Flow & Nutrient Cycles",
    videos: [
      { id: 1, title: "Energy in Ecosystems", url: "https://www.youtube.com/embed/eTKjDu1Nwlc" },
      { id: 2, title: "Food Chains & Webs", url: "https://www.youtube.com/embed/bSt6HKMUVMg" },
      { id: 3, title: "The Carbon Cycle", url: "https://www.youtube.com/embed/EGnKZG1YFzQ" },
      { id: 4, title: "The Nitrogen Cycle", url: "https://www.youtube.com/embed/vLIq3dTKwD0" },
      { id: 5, title: "The Water Cycle", url: "https://www.youtube.com/embed/Wjv5dBYiMjk" }
    ]
  },
  {
    lesson_number: 3,
    title: "Population Dynamics",
    videos: [
      { id: 1, title: "Population Growth Patterns", url: "https://www.youtube.com/embed/cQw5TwIkqCg" },
      { id: 2, title: "Limiting Factors & Carrying Capacity", url: "https://www.youtube.com/embed/ZfXk7C3K5Xk" },
      { id: 3, title: "Population Regulation", url: "https://www.youtube.com/embed/aPVvQkHIlv4" },
      { id: 4, title: "Human Population Growth", url: "https://www.youtube.com/embed/wQWgZ7T9fzs" },
    ]
  },
  {
    lesson_number: 4,
    title: "Biodiversity & Conservation",
    videos: [
      { id: 1, title: "What is Biodiversity?", url: "https://www.youtube.com/embed/p9vRVeePvnE" },
      { id: 2, title: "Extinction & Endangered Species", url: "https://www.youtube.com/embed/sL5S7hCH_Qc" },
      { id: 3, title: "Conservation Strategies", url: "https://www.youtube.com/embed/F_f4X6kS75o" },
      { id: 4, title: "Protected Areas & Reserves", url: "https://www.youtube.com/embed/mD_L7Y5XN0E" },
      { id: 5, title: "Habitat Restoration", url: "https://www.youtube.com/embed/dQw4w9WgXcQ" }
    ]
  },
  {
    lesson_number: 5,
    title: "Atmosphere & Air Quality",
    videos: [
      { id: 1, title: "Atmospheric Composition & Layers", url: "https://www.youtube.com/embed/kBGEpIi96f4" },
      { id: 2, title: "Air Pollution Sources", url: "https://www.youtube.com/embed/0RRVV4Diomg" },
      { id: 3, title: "Ozone Depletion", url: "https://www.youtube.com/embed/rcKilE9Cda0" },
      { id: 4, title: "Acid Rain", url: "https://www.youtube.com/embed/JbqtqCCwzKY" },
      { id: 5, title: "Weather & Climate Systems", url: "https://www.youtube.com/embed/BxUS1K7xu30" }
    ]
  },
  {
    lesson_number: 6,
    title: "Water Resources & Aquatic Ecosystems",
    videos: [
      { id: 1, title: "Freshwater Systems", url: "https://www.youtube.com/embed/iLLJNzvKXSs" },
      { id: 2, title: "Marine Ecosystems", url: "https://www.youtube.com/embed/ZsY4WcQOrfk" },
      { id: 3, title: "Water Pollution", url: "https://www.youtube.com/embed/d_idWp_T_I0" },
      { id: 4, title: "Eutrophication & Dead Zones", url: "https://www.youtube.com/embed/QXT4OVM4vXI" },
      { id: 5, title: "Water Conservation", url: "https://www.youtube.com/embed/PVL24HAesnc" }
    ]
  },
  {
    lesson_number: 7,
    title: "Climate Change & Global Warming",
    videos: [
      { id: 1, title: "What is Climate Change?", url: "https://www.youtube.com/embed/Y3gKOv8En7k" },
      { id: 2, title: "Greenhouse Gas Effect", url: "https://www.youtube.com/embed/a8LF7JEb0IA" },
      { id: 3, title: "Global Warming Impacts", url: "https://www.youtube.com/embed/cPDptcUwAtk" },
      { id: 4, title: "Carbon Footprint & Solutions", url: "https://www.youtube.com/embed/BqQJPC79UHU" },
    ]
  },
  {
    lesson_number: 8,
    title: "Natural Resources & Energy",
    videos: [
      { id: 1, title: "Renewable Energy Sources", url: "https://www.youtube.com/embed/FVEIuqpFoKQ" },
      { id: 2, title: "Fossil Fuels & Non-Renewable Resources", url: "https://www.youtube.com/embed/9h2f1Bjr9qo" },
      { id: 3, title: "Sustainable Energy Solutions", url: "https://www.youtube.com/embed/g5wNg_dKsYY" },
      { id: 4, title: "Soil & Mineral Resources", url: "https://www.youtube.com/embed/DP-vWN1yXrY" },
      { id: 5, title: "Resource Management", url: "https://www.youtube.com/embed/LS67ov39LFQ" }
    ]
  },
  {
    lesson_number: 9,
    title: "Waste Management & Sustainability",
    videos: [
      { id: 1, title: "Waste Management Systems", url: "https://www.youtube.com/embed/aPVvQkHIlv4" },
      { id: 2, title: "Recycling & Composting", url: "https://www.youtube.com/embed/8Fdt5WnYn1k" },
      { id: 3, title: "Plastic Pollution Crisis", url: "https://www.youtube.com/embed/7qOFtL3VEBc" },
      { id: 4, title: "Circular Economy Principles", url: "https://www.youtube.com/embed/4E7vO3Lid6U" },
    ]
  },
  {
    lesson_number: 10,
    title: "Environmental Policy & Global Action",
    videos: [
      { id: 1, title: "Environmental Laws & Regulations", url: "https://www.youtube.com/embed/UloIw7dhnlQ" },
      { id: 2, title: "International Environmental Agreements", url: "https://www.youtube.com/embed/vV_Xshb-G5U" },
      { id: 3, title: "Corporate & Social Responsibility", url: "https://www.youtube.com/embed/FSyAehMdpyI" },
      { id: 4, title: "Individual Environmental Action", url: "https://www.youtube.com/embed/rcKilE9Cda0" },
      { id: 5, title: "Sustainable Futures", url: "https://www.youtube.com/embed/UL1jmJaUkaQ" }
    ]
  }
];

export default function EnvironmentalScience() {
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    setLessons(ENVIRONMENTAL_SCIENCE_LESSONS);
  }, []);

  const handleLessonClick = (lesson) => {
    navigate("/lesson", { state: { lesson } });
  };

  return (
    <div className="page-container">
      <Sidebar />
      <div className="content">
        <h1>Environmental Science</h1>
        <div className="lessons-grid">
          {lessons.map((lesson) => (
            <div key={lesson.lesson_number} className="lesson-card" onClick={() => handleLessonClick(lesson)}>
              <h3>Lesson {lesson.lesson_number}</h3>
              <p>{lesson.title}</p>
              <span className="video-count">{lesson.videos.length} videos</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
